def transform(grid):
    if not grid or not grid[0]:
        return grid

    rows = len(grid)
    cols = len(grid[0])

    # Count occurrences to find background color
    from collections import Counter
    counts = Counter()
    for row in grid:
        for cell in row:
            counts[cell] += 1

    # Background is the most frequent color
    background = counts.most_common(1)[0][0]

    # Create output grid
    output = [[0 for _ in range(cols)] for _ in range(rows)]

    # Fill with background first
    for r in range(rows):
        for c in range(cols):
            output[r][c] = background

    # Move non-background pixels diagonally up-right (row-1, col+1)
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] != background:
                new_r = r - 1
                new_c = c + 1
                if 0 <= new_r < rows and 0 <= new_c < cols:
                    output[new_r][new_c] = grid[r][c]

    return output
