def transform(grid):
    if not grid or not grid[0]:
        return grid

    # Find background color - most frequent
    from collections import Counter
    counts = Counter()
    for row in grid:
        for cell in row:
            counts[cell] += 1
    bg = counts.most_common(1)[0][0]

    r, c = len(grid), len(grid[0])
    out = [[bg] * c for _ in range(r)]

    # Shift down by 1 row: each output row gets the input row above it
    for i in range(1, r):
        for j in range(c):
            out[i][j] = grid[i-1][j]

    return out
